			assertEquals("READY", status.auxiliaryMaintenance());
			assertFalse(status.referenceCountVerificationPending());
			assertFalse(status.retainedValueMaintenance());
			assertTrue(status.backgroundWorkPending(),
					"an auxiliary initializer cannot conceal a still-running optional build");
