	private static void createAllPhysicalTermTrees(Path storeDirectory) throws IOException {
		long environment = 0L;
		try (MemoryStack stack = MemoryStack.stackPush()) {
			var handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			environment = handle.get(0);
			E(mdb_env_set_maxdbs(environment, 64));
			E(mdb_env_open(environment, storeDirectory.resolve("values").toString(), MDB_NOTLS, 0664));
			LmdbUtil.writeTransaction(environment, (inner, txn) -> {
				var database = inner.mallocInt(1);
				for (String permutation : allPermutations("spoc").split(",")) {
					E(mdb_dbi_open(txn, TripleIndex.nativeDatabaseName("term-" + permutation, true), MDB_CREATE,
							database));
				}
				return null;
			});
		} finally {
			if (environment != 0L) {
				mdb_env_close(environment);
			}
		}
	}

	private static void populate(Path directory, LmdbStoreConfig config) {
		SailRepository repository = new SailRepository(new LmdbStore(directory.toFile(), config));
		try (var connection = repository.getConnection()) {
			var vf = SimpleValueFactory.getInstance();
			connection.begin();
			connection.setNamespace("bounded", "urn:bounded:");
			for (int i = 0; i < 1_100; i++) {
				connection.add(vf.createIRI("urn:bounded:subject:" + i), vf.createIRI("urn:bounded:predicate"),
						vf.createLiteral("dictionary payload " + i));
			}
			connection.commit();
		} finally {
			repository.shutDown();
		}
	}

	private static String read(Path path) {
		try {
			return Files.readString(path);
		} catch (IOException failure) {
			return failure.toString();
		}
	}

	private static String allPermutations(String components) {
		List<String> indexes = new ArrayList<>();
		permutations("", components, indexes);
		return String.join(",", indexes);
	}

	private static void permutations(String prefix, String remaining, List<String> indexes) {
		if (remaining.isEmpty()) {
			indexes.add(prefix);
			return;
		}
		for (int i = 0; i < remaining.length(); i++) {
			permutations(prefix + remaining.charAt(i), remaining.substring(0, i) + remaining.substring(i + 1), indexes);
		}
	}

