	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void offlineVerificationUsesThePersistedCurrentValueCodec(boolean inline) throws Exception {
		var config = new LmdbStoreConfig().setInlineLiterals(inline);
		var repository = new SailRepository(new LmdbStore(directory.toFile(), config));
		try (var connection = repository.getConnection()) {
			var vf = SimpleValueFactory.getInstance();
			var predicate = vf.createIRI("urn:verify:predicate");
			connection.begin();
			var inner = vf.createTripleTerm(vf.createBNode("inner"), predicate,
					vf.createLiteral("nested long scalar payload ".repeat(16)));
			var outer = vf.createTripleTerm(vf.createIRI("urn:verify:nested"), predicate, inner);
			connection.add(vf.createIRI("urn:verify:subject"), predicate, outer);
			for (var literal : List.of(vf.createLiteral(true), vf.createLiteral(42),
					vf.createLiteral("2026-10-23T12:13:14Z", XSD.DATETIME),
					vf.createLiteral("2026-10-23T12:13:14.000Z", XSD.DATETIME),
					vf.createLiteral("12.50", XSD.DECIMAL), vf.createLiteral("opaque", vf.createIRI("urn:datatype")),
					vf.createLiteral("language", "en"), vf.createLiteral("not-an-integer", XSD.INTEGER))) {
				connection.add(vf.createIRI("urn:verify:subject"), predicate, literal,
						vf.createIRI("urn:verify:graph"));
			}
			connection.commit();
		} finally {
			repository.shutDown();
		}
		LmdbStore.verifyStoreOffline(directory.toFile(), config);
	}

