	@Test
	void startupDoesNotReclaimOrDrainRetirementQueues() throws Exception {
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", directory);
		List<LmdbStartupDiagnostics.Operation> operations = new ArrayList<>();
		var repository = new SailRepository(new LmdbStore(directory.toFile(), new LmdbStoreConfig()));
		LmdbStartupDiagnostics.OBSERVER.set(operations::add);
		try {
			repository.init();
			assertFalse(operations.contains(LmdbStartupDiagnostics.Operation.VALUE_RECLAMATION),
					"foreground readiness must not reclaim dictionary values");
			assertFalse(operations.contains(LmdbStartupDiagnostics.Operation.RETIREMENT_RECOVERY),
					"foreground readiness must not drain durable retirement candidates");
		} finally {
			LmdbStartupDiagnostics.OBSERVER.remove();
			repository.shutDown();
		}
	}

